require_once 'config/database.php';require_once 'includes/functions.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([$id]);$p=$s->fetch();if(!$p)die('Product not found.');$pageTitle=$p['name'];$reviewErr='';
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['review'])){if(!logged()){go('login.php');}$rating=max(1,min(5,(int)($_POST['rating']??5)));$comment=trim($_POST['comment']??'');if($comment){$s=$pdo->prepare('INSERT INTO reviews(user_id,product_id,rating,comment) VALUES(?,?,?,?)');$s->execute([(int)$_SESSION['user']['id'],$id,$rating,$comment]);flash('success','Review submitted successfully.');go('product.php?id='.$id);}else $reviewErr='Please write a review.';}
$reviews=$pdo->prepare("SELECT r.*,u.name FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.product_id=? ORDER BY r.id DESC");$reviews->execute([$id]);$reviews=$reviews->fetchAll();require 'includes/header.php';?>
<section class="container detail"><img src="<?=e($p['image'])?>" alt="<?=e($p['name'])?>"><div><span class="tag"><?=e($p['category'])?></span><h1><?=e($p['name'])?></h1><div class="price">₹<?=number_format((float)$p['price'],2)?></div><p style="color:#aaa"><?=e($p['description'])?></p><form action="actions/add_to_cart.php" method="post"><input type="hidden" name="product_id" value="<?=$p['id']?>"><div class="group"><label>Quantity</label><input class="input" type="number" name="quantity" min="1" value="1" style="width:100px"></div><button class="btn">Add to Cart</button> <a class="btn secondary" href="actions/wishlist.php?id=<?=$p['id']?>">♡ Wishlist</a></form></div></section>
<section class="section"><div class="container"><div class="eyebrow">Customer Feedback</div><h2>Reviews</h2><?php if($reviewErr):?><div class="alert error"><?=e($reviewErr)?></div><?php endif;?><?php if(logged()):?><form class="panel" method="post" style="margin:20px 0"><input type="hidden" name="review" value="1"><div class="group"><label>Rating</label><select class="input" name="rating"><option value="5">★★★★★ 5</option><option value="4">★★★★☆ 4</option><option value="3">★★★☆☆ 3</option><option value="2">★★☆☆☆ 2</option><option value="1">★☆☆☆☆ 1</option></select></div><div class="group"><label>Your Review</label><textarea name="comment" required></textarea></div><button class="btn">Submit Review</button></form><?php else:?><p style="color:#aaa"><a href="login.php">Login</a> to write a review.</p><?php endif;?><div class="grid"><?php foreach($reviews as $r):?><div class="panel"><strong><?=e($r['name'])?></strong><div style="color:#d7b86c;margin:7px 0"><?=str_repeat('★',(int)$r['rating'])?><?=str_repeat('☆',5-(int)$r['rating'])?></div><p style="color:#bbb"><?=e($r['comment'])?></p><small style="color:#777"><?=e($r['created_at'])?></small></div><?php endforeach;if(!$reviews):?><div class="panel"><p style="color:#aaa">No reviews yet.</p></div><?php endif;?></div></div></section><?php require 'includes/footer.php';
